ServerEvents.recipes(event => {
  function replace(id, data) {
    event.remove({id:id})
    // KubeJS 2001.6.5 remove/forEachRecipe inspect only originalRecipes.
    // Earlier policy passes may already have queued this ID in addedRecipes.
    event.addedRecipes.removeIf(recipe => String(recipe.getId()) === id)
    event.custom(data).id(id)
  }
  Object.keys(EC_KITCHEN_RECIPES).forEach(id => replace(id, EC_KITCHEN_RECIPES[id]))
  // The legacy dimensional filter expands tool tags into its old FD-only list.
  // Restore the current shared knife tag for generic kitchen cuts after that pass.
  var edits = {}
  function normalizeKnife(recipe) {
    if (recipe.removed || String(recipe.getType()) !== 'farmersdelight:cutting') return
    if (String(recipe.getId()) === 'farmersdelight:cutting/tag_dough') return
    recipe.serialize()
    var data = JSON.parse(recipe.json.toString())
    if (data.tool && data.tool.tag === 'forge:tools/knives') return
    var tool = JSON.stringify(data.tool || {})
    var legacy = tool.match(/farmersdelight:(?:flint|iron|golden|diamond)_knife/g) || []
    if (legacy.length >= 2 || /forge:tools\/knives|farmersdelight:tools\/knives|knife_dig/.test(tool)) {
      data.tool = {tag:'forge:tools/knives'}
      edits[String(recipe.getId())] = data
    }
  }
  event.forEachRecipe({type:'farmersdelight:cutting'}, normalizeKnife)
  event.addedRecipes.forEach(normalizeKnife)
  Object.keys(edits).forEach(id => replace(id, edits[id]))
})
